        raise NotImplementedError('Doesn"t implemented yet')

class Direction(Enum):
    North = 0
    South = 1
    East = 2
    West = 3

class Room(MapSide):
    def __init__(self, roomNo):
        self._roomNumber = int(roomNo)
        self._sides = [MapSide]*4

    def enter(self):
        pass

    def set_side(self, Direction, MapSide):
        self._sides[Direction] = MapSide

    def get_side(self, Direction):
        return self._sides[Direction]

class Wall(MapSide):
    def enter(self):
        pass

class Door(MapSide):
    def __init__(self, Room1=None, Room2=None):
        self._room1 = Room1
        self._room2 = Room2
        self._isOpen = False

    def enter(self):
        pass

    def other_side(self, Room):
        if 1 == Room._roomNumber:
            other_room = self._room2
        else:
            other_room = self._room1
        return other_room

class Maze:
    def __init__(self):
        self._rooms = {}

    def set_room(self, room):
        self._rooms[room._roomNumber] = room

    def get_room_number(self, room_number):
        return self._rooms[room_number]

class MazeFactory:
    @classmethod
    def make_maze(cls):
        return Maze()

    @classmethod
    def make_wall(cls):
        return Wall()

    @classmethod
    def make_door(cls, r1, r2):
        return Door(r1, r2)

    @classmethod
